  '기본값: {v}': ['Default: {v}', '既定値: {v}', '默认值:{v}'],
  기본값으로: ['Back to default', '既定値に戻す', '恢复默认'],
  '기본값이면 이벤트를 보내는 역할이 플레이어일 때만 QTE가 뜹니다. 발신자가 「어느 쪽이든」이면 역할과 상관없이 뜹니다.':
    [
      "By default, the QTE appears only when the role sending the event is the player. If the sender is 'Either side', it appears regardless of role.",
      '既定値の場合、イベントを送信する役割がプレイヤーの時のみ QTE が表示されます。送信元が「どちらでも」の場合は役割に関係なく表示されます。',
      '默认情况下，仅当发送事件的角色为玩家时才会弹出 QTE。若发送者为“任意一方”，则无论何种角色都会弹出。',
    ],
  '기술 수치·레벨 등을 비교합니다. 현재 값은 버프·디버프를 포함하고, 기본 값은 포함하지 않습니다.': [
    'Compares a skill, the level and the like. The current value includes buffs and debuffs; the base value does not.',
    'スキル値・レベルなどを比較します。現在値はバフ・デバフを含み、基本値は含みません。',
    '比较技能数值、等级等。当前值包含增益和减益，基础值不包含。',
  ],
  '기억한 HKX 경로 {stale}개가 없어져 모드 폴더에서 다시 찾았습니다(찾음 {connected}개).': [
    '{stale} remembered HKX paths were gone and were looked up again in the mod folder ({connected} found).',
    '記憶していた HKX パス {stale} 個が見つからないため、MOD フォルダから探し直しました(見つかった数 {connected})。',
    '记住的 {stale} 个 HKX 路径已不存在，已在模组文件夹中重新查找（找到 {connected} 个）。',
  ],
  '기존 ESP/ESL의 Sound Descriptor를 사용합니다(WAV 경로가 아닙니다). Form ID는 플러그인 내부 16진수 ID입니다. 완벽 소리가 비어 있으면 성공 소리를 사용합니다.':
    [
      'Uses Sound Descriptors from existing ESP/ESL (not a WAV path). Form ID is the internal hexadecimal ID in the plugin. If Perfect sound is empty, Success sound is used.',
      '既存の ESP/ESL の Sound Descriptor を使用します（WAV パスではありません）。Form ID はプラグイン内部の16進数 ID です。パーフェクト音が空の場合は成功音を使用します。',
      '使用现有 ESP/ESL 中的 Sound Descriptor（而非 WAV 路径）。Form ID 为插件内部的十六进制 ID。若完美声音为空，则使用成功声音。',
    ],
