  '목적지를 비웠습니다. Ctrl+Z로 되돌릴 수 있습니다.': [
    'The destination was cleared. Ctrl+Z undoes it.',
    '行き先を空にしました。Ctrl+Z で元に戻せます。',
    '已清空去向。可按 Ctrl+Z 撤销。',
  ],
  '목표 연타 횟수': ['Target rapid presses', '目標連打回数', '目标连打次数'],
  몸통: ['Torso', '胴体', '躯干'],
  '몸통(COM)·목·왼 위팔 세 뼈로 가슴이 위를 보는지 검사합니다(바닐라 기상 클립을 고르는 뼈와 같음). 래그돌 회복 QTE의 결과처럼 엔진이 몸을 넘겨받는 순간 고르면 엔진이 고른 기상 자세 그대로라 결과가 엔진과 일치합니다. 서 있는 몸은 가슴이 수평이라 누움으로 셉니다.':
    [
      'Inspects whether the chest faces upward using three bones: pelvis (COM), neck, and left upper arm (the same bones used to pick vanilla get-up clips). If chosen the moment the engine takes control of the body, such as the result of a ragdoll recovery QTE, the result matches the engine because it uses the exact get-up posture picked by the engine. A standing body has a horizontal chest and is counted as lying.',
      '胴体（COM）・首・左上腕の3つのボーンで胸が上を向いているかを判定します（バニラの起き上がりクリップを選択するボーンと同じです）。ラグドール復帰 QTE の結果のようにエンジンが身体の制御を引き継ぐ瞬間に選択すると、エンジンが選択した起き上がり姿勢そのままとなるため結果がエンジンと一致します。立っている身体は胸が水平になるため仰向けとして扱われます。',
      '通过躯干（COM）、颈部和左上臂三根骨骼检测胸部是否朝上（与原版选择起身剪辑的骨骼相同）。若在引擎接管身体的瞬间进行选择（例如布娃娃恢复 QTE 的结果），由于使用的是引擎选定的起身姿势，结果将与引擎完全一致。站立的身体因胸部处于水平状态而被计为仰卧。',
    ],
  '무게가 0보다 큰 Bone이 하나 이상 필요합니다': [
    'At least one Bone with a weight above 0 is required',
    '重みが 0 より大きい Bone が 1 つ以上必要です',
    '至少需要一个权重大于 0 的 Bone',
  ],
  무기: ['Weapon', '武器', '武器'],
  '무기 {percent}%': ['Weapon {percent}%', '武器 {percent}%', '武器 {percent}%'],
  '무기 꺼내기·넣기': ['Ready weapon', '武器を構える・しまう', '拔出·收起武器'],
  '무기 데미지': ['Weapon damage', '武器ダメージ', '武器伤害'],
  '무기 데미지 %': ['Weapon damage %', '武器ダメージ %', '武器伤害 %'],
  '무기 데미지는 엔진이 그 무기로 때릴 때의 피해(기술·특성·대상 방어구 포함)에 곱합니다.': [
    "Weapon damage multiplies the damage the engine works out for a hit with that weapon (skill, perks and the target's armor included).",
    '武器ダメージは、エンジンがその武器で殴ったときのダメージ（スキル・パーク・対象の防具を含む）に掛けます。',
    '武器伤害乘以引擎用该武器击中时算出的伤害（含技能、天赋和目标护甲）。',
  ],
  '무기 뽑음': ['Weapon drawn', '武器を構えている', '已拔出武器'],
  '무기 숨김': ['Hide Weapon', '武器を隠す', '隐藏武器'],
  '무기 표시': ['Show Weapon', '武器を表示', '显示武器'],
  '무기를 넣어야 운반': ['Must sheath to carry', '武器を納めて運搬', '收起武器方可搬运'],
  '무기를 넣어야 운반: 무기·주문을 넣은 상태에서만 시작하고, 운반 중 꺼내면 대상을 떨어뜨립니다. 들기 시작 때 무기 넣기: 무기를 든 채 시작해도 들기가 시작되는 순간 동작 없이 운반자의 무기가 칼집에 들어갑니다. 그 뒤로는 무기·주문을 꺼내면 대상을 떨어뜨립니다. 대상의 무기는 놓을 때까지 보이지 않습니다.':
    [
      "Must sheath to carry: only starts when weapons and spells are sheathed; drawing them while carrying drops the target. Sheath on lift start: can start with weapons drawn, instantly sheathing carrier weapons without animation upon starting the lift. Afterwards, drawing weapons or spells drops the target. The target's weapons remain hidden until released.",
      '武器を納めて運搬: 武器・呪文を納刀した状態でのみ開始し、運搬中に構えると対象を落下させます。持ち上げ開始時に納刀: 武器を構えたまま開始しても、持ち上げが始まった瞬間に動作なしで運搬者の武器が納刀されます。それ以降は武器・呪文を構えると対象を落下させます。対象の武器は放すまで非表示になります。',
      '收起武器方可搬运：仅在收起武器·法术状态下启动，搬运中拔出则会掉落目标。抬起开始时收起武器：即使拔出武器也可启动，在开始抬起的瞬间直接将搬运者的武器收回鞘中（无动作）。此后若拔出武器·法术则掉落目标。目标的武器在放下前保持隐藏。',
    ],
  무시: ['Ignore', '無視', '忽略'],
