      '固定姿势：保持抬起动作的最终姿势附着跟随。布娃娃固定：仅将一个刚体固定在附着骨骼上，其余部分受物理摆动（使用目标骨架的布娃娃配置文件）。若无法准备布娃娃，则以固定姿势搬运。',
