      'Positions relative to the center or edges. "Screen ratio" uses screen percentage (0-100%, center 50%) (runtime default). Changing the anchor resets the position to default. You can also drag the QTE in the preview above.',
      '中央または四隅を基準に配置します。「画面比率」は画面比率（0〜100%、中央 50%）で配置します（ランタイム既定値）。基準点を変更すると位置が初期値に戻ります。上のプレビューで QTE をドラッグして移動することもできます。',
